import React from 'react';
import { Drawer, List, ListItem, ListItemText, Collapse } from '@mui/material';
import { ExpandLess, ExpandMore } from '@mui/icons-material';

function Sidebar({ selectedMenu, handleMenuClick }) {
  const [open, setOpen] = React.useState({});

  const handleClick = (menu) => {
    setOpen((prev) => ({ ...prev, [menu]: !prev[menu] }));
  };

  const menuItems = [
    {
      name: 'GenerateTool',
      subItems: [
        {name: 'Git/Svn', key: 'vcs'},
        { name: 'Enum ID', key: 'enum-id' },
        { name: 'Const Class Data', key: 'const-class-data' },
        { name: 'Class Data', key: 'class-data' },
        { name: 'Class Data ID', key: 'class-data-id' },
        { name: 'Class Data Matrix ID', key: 'class-data-matrix-id' },
       // { name: 'Custom Class Data', key: 'custom-class-data' },
        //{ name: 'Custom Class Data ID', key: 'custom-class-data-id' },
        { name: 'State', key: 'state' },
        { name: 'Behavior', key: 'behavior' },
        { name: 'Save Data', key: 'save-data' },
        { name: 'CSプロジェクト同期', key: 'csproj-sync' },
        { name: 'データ整合性チェック', key: 'data-lint' },
        { name: '一括生成ダッシュボード', key: 'generate-all' }
      ],
    },
    {
      name: 'Assets',
      subItems: [
        { name: 'Sound', key: 'sound' },
        { name: 'Texture', key: 'texture' },
        { name: 'GameObject', key: 'gameobject' },
        { name: 'Animator', key: 'animator' },
        { name: 'Scene', key: 'scene' },
        { name: 'Material', key: 'material' } 
      ],
    },
    {
      name: 'Scenario',
      subItems: [
        { name: 'ScenarioRole', key: 'scenario-role' },
        { name: 'ScenarioEvent', key: 'scenario-event' },
        { name: 'ScenarioConditions', key: 'scenario-conditions' },
        {name: "ScenarioSubGroupSettings",key : 'scenario-subgroup-setting'},
      ],
    },
    {
      name: 'Debug',
      subItems: [
        { name: 'Log', key: 'log' },
        { name: 'Command', key : 'command'}
      ],
    },
  ];

  // ワークスペース／お知らせはサブメニューを持たない単独リンク
  const singleItems = [
    { name: 'ProjectStats' },
    { name: 'Workspace' },
    { name: 'Announcements' },
    { name: 'Trash' },
    { name: 'PermissionMatrix' },
    {name : 'Documents'},
  ];

  return (
    <Drawer
      variant="permanent"
      sx={{
        width: 240,
        flexShrink: 0,
        '& .MuiDrawer-paper': {
          width: 240,
          boxSizing: 'border-box',
        },
      }}
    >
      <List>
        {singleItems.map((item) => (
          <ListItem
            button
            key={item.name}
            onClick={() => handleMenuClick(item.name, null)}
            selected={selectedMenu === item.name}
          >
            <ListItemText primary={
              item.name === 'Workspace' ? 'ワークスペース'
                : item.name === 'Trash' ? 'ゴミ箱'
                : item.name === 'ProjectStats' ? 'プロジェクト統計'
                : item.name === 'PermissionMatrix' ? '権限マトリクス'
                : item.name === 'Documents' ? '仕様書'
                : 'お知らせ'
            } />
          </ListItem>
        ))}
        {menuItems.map((item) => (
          <React.Fragment key={item.name}>
            <ListItem
              button
              onClick={() => {
                handleClick(item.name);
                handleMenuClick(item.name, null);
              }}
              selected={selectedMenu === item.name}
            >
              <ListItemText primary={item.name} />
              {open[item.name] ? <ExpandLess /> : <ExpandMore />}
            </ListItem>
            <Collapse in={open[item.name]} timeout="auto" unmountOnExit>
              <List component="div" disablePadding>
                {item.subItems.map((subItem) => (
                  <ListItem
                    button
                    key={subItem.key}
                    sx={{ pl: 4 }}
                    onClick={() => handleMenuClick(item.name, subItem.key)}
                    selected={selectedMenu === item.name && subItem.key === selectedMenu}
                  >
                    <ListItemText primary={subItem.name} />
                  </ListItem>
                ))}
              </List>
            </Collapse>
          </React.Fragment>
        ))}
      </List>
    </Drawer>
  );
}

export default Sidebar;
