// ============================================================
// class_data / CustomClassData のネストしたフィールドを描画するとき、
// BaseRoleInputForm は自分自身を再帰的にレンダーする(下の方の renderField 参照)。
// 以前は再帰した各階層が独立に enumValues/classDataSchemas/customClassSchemas を
// フェッチしていたため、ネストが深いRoleほど /api/enum-id・/api/class-data-id・
// /api/class-data・/api/custom-class-data-type-options とその配下の個別フェッチが
// 階層の数だけ重複して走り、「データ編集がクッソ重い」原因になっていた。
// 最上位のインスタンスだけがフェッチを行い、結果をこのContext経由でネストした
// 子インスタンスへ配る(子は自分ではフェッチしない)ことで、通信を1回に減らす。
const RoleFormTypeOptionsContext = createContext(null);

// Vector のラベル定義
const VECTOR_AXIS_LABELS = {
  vector2: ['X', 'Y'],
  vector3: ['X', 'Y', 'Z'],
  vector4: ['X', 'Y', 'Z', 'W'],
};

// ============================================================
// voice_ref: ScenarioVoice Matrix の List<SoundID> インデックス選択
// （Voice専用Role(VoiceLine)専用の特殊フィールド型）
//
// text_list_index と同じ仕組みで動く:
//   - ScenarioVoice Matrix: 行 = Language / 列 = ScenarioEvent("{イベント名}_{サブイベント名}")
//     / voices フィールド = SoundID の配列
//   - Role に保存する値は int（voices 配列のインデックス、-1 = 未選択）
//   - eventId / subId は ScenarioEventTransition.js から伝播される
//
// text_list_index との違い:
//   選んだインデックスが本当に狙ったボイスかを耳で確かめられるよう、
//   /api/sound/serve でサンプル再生できる。言語(Ja / En など、Matrixの行)を
//   切り替えれば、同じインデックスを別言語で聞き比べられる。
//   ドロップダウンの各候補にも試聴ボタンがあり、選ばずに聞ける。
//
// options: { matrixName, fieldName, previewLanguage }
// ============================================================

// "SoundID.Scenario_Test_Line001" / "Scenario_Test_Line001" どちらでも末尾の名前だけ取り出す
const stripSoundIdPrefix = (v) => {
  if (v == null) return '';
  const s = String(v);
  return s.includes('.') ? s.split('.').pop() : s;
};

// /api/sound のレスポンスから「SoundID名 → 再生に必要な情報」の対応表を作る。
// SoundID の命名規則は {group}_{subgroup}_{name}。nest_path を持つ定義にも
// 対応できるよう、subgroup 版と nest_path 版の両方のキーを登録しておく。
const buildSoundLookup = (soundData) => {
  const map = new Map();
  Object.entries(soundData?.groups || {}).forEach(([groupName, groupValue]) => {
    (groupValue?.items || []).forEach((item, index) => {
      const entry = { group: groupName, index, name: item.name, desc: item.desc || '', type: item.type };
      const nest = Array.isArray(item.nest_path) ? item.nest_path : [];
      const keys = new Set([
        [groupName, item.subgroup, item.name].filter(Boolean).join('_'),
        [groupName, ...nest, item.name].join('_'),
      ]);
      keys.forEach((k) => { if (!map.has(k)) map.set(k, entry); });
    });
  });
  return map;
};

// セル(1つのシナリオ×言語)から voices の配列を取り出す。
// {value: [...]} 形式・素の配列形式のどちらでも読める。フィールド自体が無ければ null。
const extractCellList = (cell, fieldName) => {
  if (!cell || typeof cell !== 'object') return [];
  if (Array.isArray(cell)) return cell;
  const fieldCell = cell[fieldName];
  if (fieldCell === undefined) return null;
  if (fieldCell && typeof fieldCell === 'object' && 'value' in fieldCell) {
    return Array.isArray(fieldCell.value) ? fieldCell.value : [];
  }
  return Array.isArray(fieldCell) ? fieldCell : [];
};

// 試聴言語の選択は、同じ画面内の別の voice_ref フィールドにも引き継ぐ
let lastVoicePreviewLanguage = null;

function VoiceRefFieldEditor({ value, onChange, options, eventId, subId }) {
  const matrixName = options?.matrixName || 'ScenarioVoice';
  const fieldName = options?.fieldName || 'voices';
  const defaultLanguage = options?.previewLanguage || 'Ja';

  const [table, setTable] = useState(null);
  const [soundLookup, setSoundLookup] = useState(null); // null = サウンド定義を取得できなかった
  const [scenarioKey, setScenarioKey] = useState('');
  const [language, setLanguage] = useState(lastVoicePreviewLanguage || defaultLanguage);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');
  const [playingIndex, setPlayingIndex] = useState(null);
  const [playError, setPlayError] = useState('');
  const audioRef = useRef(null);

  const numericValue = (() => {
    if (typeof value === 'number' && !Number.isNaN(value)) return value;
    if (typeof value === 'string' && value.trim() !== '') {
      const n = parseInt(value, 10);
      return Number.isNaN(n) ? -1 : n;
    }
    return -1;
  })();

  useEffect(() => {
    if (!eventId || !subId) {
      setErrorMsg('シナリオイベント文脈が必要です（eventId / subId）。');
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setErrorMsg('');
    setScenarioKey('');

    (async () => {
      try {
        // 3つは互いに独立なので並列で取る。サウンド定義が取れなくても
        // インデックスの選択自体はできる（試聴だけ無効になる）。
        const [listRes, matrixRes, soundRes] = await Promise.all([
          fetch('/api/scenario-event'),
          fetch(`/api/class-data-matrix-id/${matrixName}`),
          fetch('/api/sound').catch(() => null),
        ]);
        if (!listRes.ok) throw new Error(`シナリオイベント一覧の取得に失敗 (${listRes.status})`);
        if (!matrixRes.ok) throw new Error(`Matrix ${matrixName} の取得に失敗 (${matrixRes.status})`);

        // 列キーの解決は TextListIndexFieldEditor と同じ:
        // eventId / subId は内部の安定IDなので、名前を引き直して "{イベント名}_{サブイベント名}" にする。
        const eventList = await listRes.json();
        const ev = (eventList || []).find((e) => String(e.id) === String(eventId));
        const sub = (ev?.subEvents || []).find((s) => String(s.subId) === String(subId));
        if (!ev || !sub) {
          throw new Error('このシナリオ／サブイベントが見つかりませんでした（一覧を再読み込みしてください）。');
        }
        const matrixTable = await matrixRes.json();
        let lookup = null;
        if (soundRes && soundRes.ok) {
          try { lookup = buildSoundLookup(await soundRes.json()); } catch (_) { lookup = null; }
        }
        if (cancelled) return;
        setScenarioKey(`${ev.name}_${sub.name}`);
        setTable(matrixTable);
        setSoundLookup(lookup);
      } catch (e) {
        if (!cancelled) setErrorMsg(e.message || String(e));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [eventId, subId, matrixName]);

  // Matrix の各行(=言語)から、このシナリオの列にある voices を取り出す。
  const languages = useMemo(() => {
    if (!table || !scenarioKey) return [];
    const data = table.data || {};
    return Object.keys(data).map((rowKey) => {
      const rowDict = data[rowKey] || {};
      const colKey = Object.keys(rowDict).find(
        (k) => k === scenarioKey || k === `ScenarioEventID.${scenarioKey}` || k.endsWith(`.${scenarioKey}`)
      );
      const list = colKey ? extractCellList(rowDict[colKey], fieldName) : null;
      return {
        label: rowKey.includes('.') ? rowKey.split('.').pop() : rowKey,
        colKey: colKey || null,
        list, // null = このシナリオの列 or フィールドが無い
      };
    });
  }, [table, scenarioKey, fieldName]);

  const activeLang = useMemo(
    () => languages.find((l) => l.label.toLowerCase() === String(language).toLowerCase()) || languages[0] || null,
    [languages, language]
  );

  const items = useMemo(() => {
    const list = activeLang?.list || [];
    return list.map((sid, i) => {
      const soundId = stripSoundIdPrefix(sid);
      const info = soundLookup ? soundLookup.get(soundId) || null : null;
      return {
        index: i,
        soundId,
        info,
        label: `${i} : ${soundId}${info?.desc ? ` — ${info.desc}` : ''}`,
      };
    });
  }, [activeLang, soundLookup]);

  // 言語ごとにボイス数が違うと、同じインデックスが別のセリフを指してしまう
  const lengthMismatch = useMemo(() => {
    const withList = languages.filter((l) => Array.isArray(l.list));
    if (withList.length < 2) return '';
    const lens = new Set(withList.map((l) => l.list.length));
    return lens.size > 1 ? withList.map((l) => `${l.label}:${l.list.length}件`).join(' / ') : '';
  }, [languages]);

  const stopAudio = useCallback(() => {
    const a = audioRef.current;
    if (a) {
      a.onended = null;
      a.onerror = null;
      a.pause();
      audioRef.current = null;
    }
    setPlayingIndex(null);
  }, []);

  // アンマウント時・言語切替時は再生を止める
  useEffect(() => stopAudio, [stopAudio]);
  useEffect(() => { stopAudio(); setPlayError(''); }, [language, stopAudio]);

  const playItem = (item) => {
    if (!item) return;
    if (playingIndex === item.index && audioRef.current) { stopAudio(); return; }
    stopAudio();
    setPlayError('');
    if (!item.info) return;
    const audio = new Audio(`/api/sound/serve/${encodeURIComponent(item.info.group)}/${item.info.index}`);
    audio.onended = () => { if (audioRef.current === audio) { audioRef.current = null; setPlayingIndex(null); } };
    audio.onerror = () => {
      if (audioRef.current === audio) { audioRef.current = null; setPlayingIndex(null); }
      setPlayError(`${item.soundId} の音声ファイルを再生できませんでした。`);
    };
    audioRef.current = audio;
    setPlayingIndex(item.index);
    audio.play().catch(() => {
      if (audioRef.current === audio) { audioRef.current = null; setPlayingIndex(null); }
    });
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <CircularProgress size={16} />
        <Typography variant="caption" color="text.secondary">ボイス一覧を読み込み中...</Typography>
      </Box>
    );
  }

  if (errorMsg) {
    return <Typography variant="caption" color="error">{errorMsg}</Typography>;
  }

  if (languages.length === 0) {
    return (
      <Typography variant="caption" color="error">
        Matrix {matrixName} に言語の行がありません。Matrix にボイスを追加してください。
      </Typography>
    );
  }

  const selected = items.find((o) => o.index === numericValue) || null;
  const isPlayingSelected = selected != null && playingIndex === selected.index;

  return (
    <Box>
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 0.5 }}>
        {matrixName}.{fieldName}（{activeLang?.label}） / シナリオ {scenarioKey || eventId} — {items.length}件
      </Typography>

      {languages.length > 1 && (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
          <Typography variant="caption" color="text.secondary">試聴言語</Typography>
          <ToggleButtonGroup
            exclusive
            size="small"
            value={activeLang?.label}
            onChange={(e, v) => {
              if (!v) return;
              lastVoicePreviewLanguage = v;
              setLanguage(v);
            }}
          >
            {languages.map((l) => (
              <ToggleButton key={l.label} value={l.label} sx={{ py: 0, px: 1, textTransform: 'none' }}>
                {l.label}
              </ToggleButton>
            ))}
          </ToggleButtonGroup>
        </Box>
      )}

      {activeLang && activeLang.list === null && (
        <Typography variant="caption" color="error" sx={{ display: 'block', mb: 0.5 }}>
          Matrix {matrixName}（{activeLang.label}）に「{scenarioKey}」の {fieldName} がありません。
          scenario_matrix_editor.py のボイス設定などで追加してください。
        </Typography>
      )}
      {lengthMismatch && (
        <Typography variant="caption" color="warning.main" sx={{ display: 'block', mb: 0.5 }}>
          言語ごとのボイス数が一致していません（{lengthMismatch}）。同じインデックスが別言語で別のセリフを指す恐れがあります。
        </Typography>
      )}

      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
        <Autocomplete
          size="small"
          sx={{ flex: 1 }}
          options={items}
          value={selected}
          onChange={(e, v) => onChange(v ? v.index : -1)}
          getOptionLabel={(o) => (o ? o.label : '')}
          isOptionEqualToValue={(a, b) => a?.index === b?.index}
          renderInput={(params) => <TextField {...params} label="ボイスインデックス" />}
          renderOption={(props, option) => {
            const { key, ...liProps } = props;
            const playing = playingIndex === option.index;
            return (
              <li key={key} {...liProps}>
                <Box sx={{ display: 'flex', alignItems: 'center', width: '100%', gap: 0.5 }}>
                  <Typography variant="body2" sx={{ flex: 1, minWidth: 0, wordBreak: 'break-all' }}>
                    {option.label}
                  </Typography>
                  <Tooltip title={option.info ? (playing ? '停止' : '試聴') : 'サウンド定義が見つかりません'}>
                    <span>
                      <IconButton
                        size="small"
                        disabled={!option.info}
                        onMouseDown={(e) => e.stopPropagation()}
                        onClick={(e) => { e.stopPropagation(); playItem(option); }}
                      >
                        {playing ? <StopIcon fontSize="small" /> : <PlayArrowIcon fontSize="small" />}
                      </IconButton>
                    </span>
                  </Tooltip>
                </Box>
              </li>
            );
          }}
          noOptionsText="このシナリオ×言語のボイスがありません。Matrix に追加してください。"
        />
        <Tooltip title={selected?.info ? (isPlayingSelected ? '停止' : '選択中のボイスを試聴') : '試聴できません'}>
          <span>
            <IconButton disabled={!selected?.info} onClick={() => playItem(selected)}>
              {isPlayingSelected ? <StopIcon /> : <PlayArrowIcon />}
            </IconButton>
          </span>
        </Tooltip>
      </Box>

      {selected && !selected.info && (
        <Typography variant="caption" color="warning.main" sx={{ display: 'block', mt: 0.5 }}>
          {soundLookup
            ? `SoundID「${selected.soundId}」に対応するサウンド定義が見つかりません（削除・リネームされた可能性があります）。`
            : 'サウンド定義(/api/sound)を取得できなかったため試聴できません。'}
        </Typography>
      )}
      {numericValue >= 0 && !selected && activeLang?.list && (
        <Typography variant="caption" color="warning.main" sx={{ display: 'block', mt: 0.5 }}>
          インデックス {numericValue} は {activeLang.label} のボイス一覧（{items.length}件）の範囲外です。
        </Typography>
      )}
      {playError && (
        <Typography variant="caption" color="error" sx={{ display: 'block', mt: 0.5 }}>{playError}</Typography>
      )}
    </Box>
  );
}

// ============================================================
// text_list_index: ScenarioText Matrix の List<string> インデックス選択
// options: { matrixName, fieldName, previewLanguage }
// 値は int（インデックス）。プレビューは指定言語のテキストを表示。
// ============================================================
function TextListIndexFieldEditor({ value, onChange, options, eventId, subId }) {
  const matrixName = options?.matrixName || 'ScenarioText';
  const fieldName = options?.fieldName || 'texts';
  const previewLanguage = options?.previewLanguage || 'Ja';
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState('');
  const [scenarioKey, setScenarioKey] = useState('');

  const numericValue = (() => {
    if (typeof value === 'number' && !Number.isNaN(value)) return value;
    if (typeof value === 'string' && value.trim() !== '') {
      const n = parseInt(value, 10);
      return Number.isNaN(n) ? -1 : n;
    }
    return -1;
  })();

  useEffect(() => {
    if (!eventId || !subId) {
      setErrorMsg('シナリオイベント文脈が必要です（eventId / subId）。');
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setErrorMsg('');
    setScenarioKey('');

    (async () => {
      try {
        // ── 列キーの解決 ───────────────────────────────────────────
        // ScenarioText Matrix の列は class_data_id 側の ScenarioEvent テーブルであり、
        // その行識別子(enum_property)は scenario.py の class_id_generate() が
        //     "{イベント名}_{サブイベント名}"   （例: "Z99999_test"）
        // という形で採番している。
        // 一方このフォームに渡ってくる eventId / subId は scenario_event_list.json の
        // 内部ID(リネームに強い安定ID)であって「名前」ではないため、
        // 以前のように eventId をそのまま列キーとして照合しても絶対に一致せず、
        // 常に候補0件（＝「このシナリオ×言語のテキストがありません」）になっていた。
        // そこでまずイベント一覧から名前を引き直し、正しい列キーを組み立てる。
        const listRes = await fetch('/api/scenario-event');
        if (!listRes.ok) throw new Error(`シナリオイベント一覧の取得に失敗 (${listRes.status})`);
        const eventList = await listRes.json();
        const ev = (eventList || []).find((e) => String(e.id) === String(eventId));
        const sub = (ev?.subEvents || []).find((s) => String(s.subId) === String(subId));
        if (!ev || !sub) {
          throw new Error('このシナリオ／サブイベントが見つかりませんでした（一覧を再読み込みしてください）。');
        }
        const wantKey = `${ev.name}_${sub.name}`;
        if (!cancelled) setScenarioKey(wantKey);

        const r = await fetch(`/api/class-data-matrix-id/${matrixName}`);
        if (!r.ok) throw new Error(`Matrix ${matrixName} の取得に失敗 (${r.status})`);
        const table = await r.json();
        if (cancelled) return;

        const data = table.data || {};
        // rowKey は Language の enum_property（Ja 等）
        const rowKeys = Object.keys(data);
        const langKey = rowKeys.find((k) => k === previewLanguage || k.endsWith(`.${previewLanguage}`) || k === `LanguageID.${previewLanguage}`)
          || rowKeys.find((k) => String(k).toLowerCase() === String(previewLanguage).toLowerCase());
        if (!langKey) {
          throw new Error(`Matrix ${matrixName} に言語 "${previewLanguage}" の行がありません（存在する行: ${rowKeys.join(', ') || 'なし'}）。`);
        }

        const rowDict = data[langKey] || {};
        // colKey: "{イベント名}_{サブイベント名}"、あるいは "ScenarioEventID." 等の
        // 修飾付きで保存されている場合にも対応する。
        const colKeys = Object.keys(rowDict);
        const colKey = colKeys.find((k) => k === wantKey || k === `ScenarioEventID.${wantKey}` || k.endsWith(`.${wantKey}`));
        if (!colKey) {
          throw new Error(`Matrix ${matrixName}（${previewLanguage}）に列 "${wantKey}" がありません。Matrix 側にこのシナリオの行を追加してください。`);
        }

        const cell = rowDict[colKey] || {};
        let list = [];
        if (cell && typeof cell === 'object') {
          const fieldCell = cell[fieldName];
          if (fieldCell && typeof fieldCell === 'object' && 'value' in fieldCell) {
            list = Array.isArray(fieldCell.value) ? fieldCell.value : [];
          } else if (Array.isArray(fieldCell)) {
            list = fieldCell;
          } else if (Array.isArray(cell)) {
            list = cell;
          } else if (fieldCell === undefined) {
            throw new Error(`列 "${wantKey}" にフィールド "${fieldName}" がありません（このMatrixのフィールド: ${Object.keys(cell).join(', ') || 'なし'}）。`);
          }
        }
        setItems(list.map((t, i) => ({
          index: i,
          label: `${i} : ${typeof t === 'string' ? t : String(t ?? '')}`,
          text: typeof t === 'string' ? t : String(t ?? ''),
        })));
      } catch (e) {
        if (!cancelled) setErrorMsg(e.message || String(e));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [eventId, subId, matrixName, fieldName, previewLanguage]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <CircularProgress size={16} />
        <Typography variant="caption" color="text.secondary">テキスト一覧を読み込み中...</Typography>
      </Box>
    );
  }

  if (errorMsg) {
    return <Typography variant="caption" color="error">{errorMsg}</Typography>;
  }

  const selected = items.find((o) => o.index === numericValue) || null;

  return (
    <Box>
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 0.5 }}>
        {matrixName}.{fieldName}（{previewLanguage}） / シナリオ {scenarioKey || eventId} — {items.length}件
      </Typography>
      <Autocomplete
        size="small"
        options={items}
        value={selected}
        onChange={(e, v) => onChange(v ? v.index : -1)}
        getOptionLabel={(o) => (o ? o.label : '')}
        isOptionEqualToValue={(a, b) => a?.index === b?.index}
        renderInput={(params) => <TextField {...params} label="テキストインデックス" />}
        noOptionsText="このシナリオ×言語のテキストがありません。Matrix に追加してください。"
      />
    </Box>
  );
}

// ============================================================
// bit / color / bezier 値エディタ
// (CustomClassDataIdDetailGrid.js の編集UIと同じ挙動・データ形式に揃えてある)
// ============================================================
function BitValueEditor({ value, options, onChange }) {
  const size = options?.size ?? value?.size ?? 8;
  const flagNames = options?.flagNames && options.flagNames.length === size
    ? options.flagNames
    : Array.from({ length: size }, (_, i) => `Flag${i}`);
  const bits = Array.isArray(value?.bits) ? value.bits : [];
  const isSingle = options?.mode === 'single';
  const [search, setSearch] = useState('');

  const toggle = (i) => {
    if (isSingle) { onChange({ size, bits: [i] }); return; }
    const has = bits.includes(i);
    onChange({ size, bits: has ? bits.filter(b => b !== i) : [...bits, i] });
  };

  const entries = useMemo(() => flagNames.map((label, i) => ({ label, i })), [flagNames]);
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return entries;
    return entries.filter(({ label }) => label.toLowerCase().includes(q));
  }, [entries, search]);

  return (
    <Box sx={{ display: 'flex', border: '1px solid #e0e0e0', borderRadius: 2, overflow: 'hidden', bgcolor: '#fff' }}>
      {/* 左: サマリー + 一括操作 */}
      <Box sx={{ width: 160, flexShrink: 0, p: 1.5, bgcolor: '#f7f8fa', borderRight: '1px solid #eee' }}>
        <Typography variant="caption" color="text.secondary">選択中</Typography>
        <Typography variant="h6" sx={{ fontWeight: 700, lineHeight: 1.2, color: 'primary.main' }}>
          {bits.length}
          <Typography component="span" variant="caption" color="text.secondary"> / {size}</Typography>
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75, mt: 1.5 }}>
          {!isSingle && options?.allowSelectAll && (
            <Button size="small" variant="outlined" onClick={() => onChange({ size, bits: Array.from({ length: size }, (_, i) => i) })}>全選択</Button>
          )}
          <Button size="small" variant="outlined" color="secondary" onClick={() => onChange({ size, bits: [] })}>クリア</Button>
        </Box>
        {isSingle && (
          <Typography variant="caption" color="text.disabled" sx={{ display: 'block', mt: 1.5 }}>
            単一選択モード
          </Typography>
        )}
      </Box>

      {/* 右: 検索 + 縦一列のスクロール可能なフラグ一覧 */}
      <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
        <Box sx={{ p: 1, borderBottom: '1px solid #eee', bgcolor: '#fff' }}>
          <TextField
            size="small"
            fullWidth
            placeholder={`フラグを検索 (${flagNames.length}件)`}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Box>
        <Box sx={{ maxHeight: 220, overflowY: 'auto' }}>
          {filtered.length === 0 && (
            <Typography variant="caption" color="text.disabled" sx={{ display: 'block', p: 2, textAlign: 'center' }}>
              該当するフラグがありません
            </Typography>
          )}
          {filtered.map(({ label, i }) => {
            const checked = bits.includes(i);
            return (
              <Box
                key={i}
                onClick={() => toggle(i)}
                sx={{
                  display: 'flex', alignItems: 'center', gap: 1, pl: 0.5, pr: 1.5, py: 0.25, cursor: 'pointer',
                  borderLeft: '3px solid',
                  borderLeftColor: checked ? 'primary.main' : 'transparent',
                  bgcolor: checked ? 'rgba(25, 118, 210, 0.08)' : (i % 2 === 0 ? '#fff' : '#fafafa'),
                  '&:hover': { bgcolor: checked ? 'rgba(25, 118, 210, 0.14)' : '#f0f0f0' },
                }}
              >
                <Checkbox size="small" checked={checked} onChange={() => toggle(i)} onClick={(e) => e.stopPropagation()} />
                <Typography variant="body2" sx={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={label}>{label}</Typography>
                <Typography variant="caption" color="text.disabled">#{i}</Typography>
              </Box>
            );
          })}
        </Box>
      </Box>
    </Box>
  );
}

function toHex(v) {
  return Math.round(Math.max(0, Math.min(1, v)) * 255).toString(16).padStart(2, '0');
}
function ColorValueEditor({ value, onChange }) {
  const v = value && typeof value === 'object' ? value : { r: 1, g: 1, b: 1, a: 1 };
  const hex = `#${toHex(v.r)}${toHex(v.g)}${toHex(v.b)}`;
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
      <input
        type="color"
        value={hex}
        onChange={(e) => {
          const h = e.target.value;
          onChange({
            r: parseInt(h.slice(1, 3), 16) / 255,
            g: parseInt(h.slice(3, 5), 16) / 255,
            b: parseInt(h.slice(5, 7), 16) / 255,
            a: v.a,
          });
        }}
        style={{ width: 44, height: 32, border: 'none', background: 'none', cursor: 'pointer' }}
      />
      <Box sx={{ width: 160 }}>
        <Typography variant="caption">アルファ: {(v.a ?? 1).toFixed(2)}</Typography>
        <Slider size="small" min={0} max={1} step={0.01} value={v.a ?? 1} onChange={(e, nv) => onChange({ ...v, a: nv })} />
      </Box>
      <Box sx={{ width: 28, height: 28, borderRadius: 1, border: '1px solid #ccc', background: `rgba(${v.r * 255},${v.g * 255},${v.b * 255},${v.a})` }} />
    </Box>
  );
}

function hermite(p0, p1, t) {
  const dt = p1.time - p0.time || 1;
  const s = (t - p0.time) / dt;
  const h00 = 2 * s ** 3 - 3 * s ** 2 + 1;
  const h10 = s ** 3 - 2 * s ** 2 + s;
  const h01 = -2 * s ** 3 + 3 * s ** 2;
  const h11 = s ** 3 - s ** 2;
  return h00 * p0.value + h10 * dt * p0.outTangent + h01 * p1.value + h11 * dt * p1.inTangent;
}
// タンジェントハンドルの画面上の長さ（px固定。角度だけが傾き値を表す）
const TANGENT_HANDLE_LEN = 40;
// ハンドルドラッグ時、傾き計算が発散しないようx方向オフセットの最小値をpxで確保する
const TANGENT_MIN_DX = 10;

function BezierValueEditor({ value, options, onChange }) {
  const points = (value?.points && value.points.length >= 2)
    ? [...value.points].sort((a, b) => a.time - b.time)
    : [{ time: 0, value: options?.min ?? 0, inTangent: 0, outTangent: 0 }, { time: 1, value: options?.max ?? 1, inTangent: 0, outTangent: 0 }];
  const min = options?.min ?? 0;
  const max = options?.max ?? 1;
  const W = 360, H = 180, PAD = 20;
  const svgRef = useRef(null);
  const [dragIndex, setDragIndex] = useState(null);
  // アクティブ（選択中）な点。選択されている間、その点の左右にタンジェントハンドルを表示する
  const [activeIndex, setActiveIndex] = useState(null);
  // タンジェントハンドルのドラッグ状態: { index, side: 'in' | 'out' }
  const [dragHandle, setDragHandle] = useState(null);

  const sx = (W - PAD * 2); // px per unit time (time範囲は0-1)
  const sy = (H - PAD * 2) / ((max - min) || 1); // px per unit value

  const xToPx = (t) => PAD + t * (W - PAD * 2);
  const yToPx = (v) => H - PAD - ((v - min) / ((max - min) || 1)) * (H - PAD * 2);
  const pxToX = (px) => Math.max(0, Math.min(1, (px - PAD) / (W - PAD * 2)));
  const pxToY = (py) => min + (1 - (py - PAD) / (H - PAD * 2)) * (max - min);

  // タンジェント値 -> ハンドルの点からの相対オフセット（画面上の長さは固定）
  const tangentToHandleOffset = (tangent, side) => {
    const dtime = side === 'out' ? 1 : -1;
    const dvalue = side === 'out' ? tangent : -tangent;
    let dx = sx * dtime;
    let dy = -sy * dvalue;
    const len = Math.hypot(dx, dy) || 1;
    return { dx: (dx / len) * TANGENT_HANDLE_LEN, dy: (dy / len) * TANGENT_HANDLE_LEN };
  };

  // ハンドルの相対オフセット -> タンジェント値
  const handleOffsetToTangent = (dx, dy, side) => {
    const minDx = side === 'out' ? TANGENT_MIN_DX : -TANGENT_MIN_DX;
    const clampedDx = side === 'out' ? Math.max(dx, minDx) : Math.min(dx, minDx);
    return -(dy * sx) / (clampedDx * sy);
  };

  const pathD = useMemo(() => {
    let d = '';
    const steps = 24;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i], p1 = points[i + 1];
      for (let s = 0; s <= steps; s++) {
        const t = p0.time + (p1.time - p0.time) * (s / steps);
        const v = hermite(p0, p1, t);
        d += `${(i === 0 && s === 0) ? 'M' : 'L'}${xToPx(t)},${yToPx(v)} `;
      }
    }
    return d;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [points]);

  const updatePoint = (index, patch) => onChange({ points: points.map((p, i) => (i === index ? { ...p, ...patch } : p)) });
  const handleMove = (e) => {
    if (!svgRef.current) return;
    if (dragIndex === null && dragHandle === null) return;
    const rect = svgRef.current.getBoundingClientRect();
    const px = (e.clientX - rect.left) * (W / rect.width);
    const py = (e.clientY - rect.top) * (H / rect.height);
    if (dragIndex !== null) {
      updatePoint(dragIndex, { time: pxToX(px), value: pxToY(py) });
      return;
    }
    if (dragHandle !== null) {
      const p = points[dragHandle.index];
      const cx = xToPx(p.time), cy = yToPx(p.value);
      const tangent = handleOffsetToTangent(px - cx, py - cy, dragHandle.side);
      updatePoint(dragHandle.index, { [`${dragHandle.side}Tangent`]: tangent });
    }
  };
  const endDrag = () => { setDragIndex(null); setDragHandle(null); };
  const addPoint = () => onChange({ points: [...points, { time: 0.5, value: (min + max) / 2, inTangent: 0, outTangent: 0 }] });
  const removePoint = (index) => {
    if (points.length <= 2) return;
    if (activeIndex === index) setActiveIndex(null);
    onChange({ points: points.filter((_, i) => i !== index) });
  };

  return (
    <Box>
      <svg
        ref={svgRef} viewBox={`0 0 ${W} ${H}`} width="100%"
        style={{ background: '#fafafa', border: '1px solid #ddd', touchAction: 'none' }}
        onMouseMove={handleMove} onMouseUp={endDrag} onMouseLeave={endDrag}
      >
        <line x1={PAD} y1={H - PAD} x2={W - PAD} y2={H - PAD} stroke="#bbb" />
        <line x1={PAD} y1={PAD} x2={PAD} y2={H - PAD} stroke="#bbb" />
        <path d={pathD} fill="none" stroke="#1976d2" strokeWidth={2} />
        {points.map((p, i) => {
          const cx = xToPx(p.time), cy = yToPx(p.value);
          const isActive = activeIndex === i;
          const inOff = tangentToHandleOffset(p.inTangent ?? 0, 'in');
          const outOff = tangentToHandleOffset(p.outTangent ?? 0, 'out');
          const inPos = { x: cx + inOff.dx, y: cy + inOff.dy };
          const outPos = { x: cx + outOff.dx, y: cy + outOff.dy };
          return (
            <g key={i}>
              {isActive && (
                <>
                  <line x1={cx} y1={cy} x2={inPos.x} y2={inPos.y} stroke="#43a047" strokeWidth={1.5} strokeDasharray="3,2" />
                  <line x1={cx} y1={cy} x2={outPos.x} y2={outPos.y} stroke="#fb8c00" strokeWidth={1.5} strokeDasharray="3,2" />
                  <circle
                    cx={inPos.x} cy={inPos.y} r={5}
                    fill={dragHandle?.index === i && dragHandle?.side === 'in' ? '#2e7d32' : '#66bb6a'}
                    stroke="#fff" strokeWidth={1}
                    style={{ cursor: 'grab' }}
                    onMouseDown={(e) => { e.stopPropagation(); setDragHandle({ index: i, side: 'in' }); }}
                  />
                  <circle
                    cx={outPos.x} cy={outPos.y} r={5}
                    fill={dragHandle?.index === i && dragHandle?.side === 'out' ? '#e65100' : '#ffa726'}
                    stroke="#fff" strokeWidth={1}
                    style={{ cursor: 'grab' }}
                    onMouseDown={(e) => { e.stopPropagation(); setDragHandle({ index: i, side: 'out' }); }}
                  />
                </>
              )}
              <circle cx={cx} cy={cy} r={isActive ? 6 : 5}
                fill={dragIndex === i ? '#d32f2f' : (isActive ? '#1565c0' : '#1976d2')}
                stroke={isActive ? '#0d47a1' : 'none'} strokeWidth={isActive ? 2 : 0}
                style={{ cursor: 'grab' }}
                onMouseDown={(e) => { e.stopPropagation(); setActiveIndex(i); setDragIndex(i); }} />
            </g>
          );
        })}
      </svg>
      <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
        点をクリックして選択すると、左右にタンジェントハンドル（緑=in / 橙=out）が表示され、ドラッグで傾きを調整できます。
      </Typography>
      <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 0.5 }}>
        {points.map((p, i) => (
          <Box key={i} sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
            <Chip
              size="small"
              label={`点${i}`}
              color={activeIndex === i ? 'primary' : 'default'}
              onClick={() => setActiveIndex(i)}
              sx={{ cursor: 'pointer' }}
            />
            <TextField size="small" label="time" type="number" value={p.time} sx={{ width: 90 }}
              onChange={(e) => updatePoint(i, { time: Math.max(0, Math.min(1, parseFloat(e.target.value) || 0)) })} />
            <TextField size="small" label="value" type="number" value={p.value} sx={{ width: 90 }}
              onChange={(e) => updatePoint(i, { value: parseFloat(e.target.value) || 0 })} />
            <TextField size="small" label="inTangent" type="number" value={p.inTangent} sx={{ width: 90 }}
              onChange={(e) => updatePoint(i, { inTangent: parseFloat(e.target.value) || 0 })} />
            <TextField size="small" label="outTangent" type="number" value={p.outTangent} sx={{ width: 90 }}
              onChange={(e) => updatePoint(i, { outTangent: parseFloat(e.target.value) || 0 })} />
            <IconButton size="small" color="error" disabled={points.length <= 2} onClick={() => removePoint(i)}>
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Box>
        ))}
        <Button size="small" startIcon={<AddIcon />} onClick={addPoint} sx={{ alignSelf: 'flex-start' }}>点を追加</Button>
      </Box>
    </Box>
  );
}

// 数値入力コンポーネント（マイナス・小数点対応、文字列で管理）
const NumericInput = ({ label, value, onChange, isFloat = false, sx = {} }) => {
  const [inputStr, setInputStr] = useState(String(value ?? 0));

  useEffect(() => {
    // 外部からの値変化に追従（ただし入力中は上書きしない）
    const parsed = isFloat ? parseFloat(inputStr) : parseInt(inputStr, 10);
    if (!isNaN(parsed) && parsed !== value) {
      setInputStr(String(value ?? 0));
    }
  }, [value]);

  const handleChange = (e) => {
    const raw = e.target.value;
    // 途中入力として許可するパターン: "-", "-.", ".", "-.0", "0.", etc.
    const allowPattern = isFloat ? /^-?(\d*\.?\d*)?$/ : /^-?\d*$/;
    if (!allowPattern.test(raw)) return;
    setInputStr(raw);
    const parsed = isFloat ? parseFloat(raw) : parseInt(raw, 10);
    if (!isNaN(parsed)) {
      onChange(parsed);
    } else if (raw === '' || raw === '-') {
      onChange(0);
    }
  };

  const handleBlur = () => {
    // フォーカスを外れたとき、空や単なる"-"なら0に正規化
    const parsed = isFloat ? parseFloat(inputStr) : parseInt(inputStr, 10);
    if (isNaN(parsed) || inputStr === '-') {
      setInputStr('0');
      onChange(0);
    } else {
      setInputStr(String(parsed));
      onChange(parsed);
    }
  };

  return (
    <TextField
      label={label}
      value={inputStr}
      onChange={handleChange}
      onBlur={handleBlur}
      inputProps={{ inputMode: isFloat ? 'decimal' : 'numeric' }}
      sx={sx}
    />
  );
};

// ============================================================
// dictionary 値エディタ
// キーは数値のみ（int / Enum / ClassDataID / CustomClassDataID）、値は任意の型
// 値データ形式: { entries: [{ key, value }, ...] }
// ============================================================
function DictionaryScalarEditor({ type, value, options, onChange, enumValues, classDataSchemas, customClassSchemas }) {
  const lower = (type || '').toLowerCase();
  // subSchemaはHooksのルール上、早期returnより前で無条件に(useMemoとして)
  // 組み立てておく必要がある。ここで毎回新しいオブジェクトを作ってしまうと
  // NestedClassDataField側のuseMemoの依存配列([...、subSchema])が常に変化した
  // ことになり、せっかくのメモ化が効かなくなってしまう。
  const nestedSchema = customClassSchemas[type] || classDataSchemas[type];
  const nestedSubSchema = useMemo(() => {
    if (!nestedSchema || nestedSchema.length === 0) return null;
    return {
      fields: nestedSchema.map(sub => ({
        ...sub,
        label: sub.label || sub.name,
        arraySize: sub.arraySize !== undefined ? sub.arraySize : 0,
      })),
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nestedSchema]);

  if (lower === 'bit') return <BitValueEditor value={value} options={options} onChange={onChange} />;
  if (lower === 'color') return <ColorValueEditor value={value} onChange={onChange} />;
  if (lower === 'bezier') return <BezierValueEditor value={value} options={options} onChange={onChange} />;
  if (lower === 'bool') {
    return (
      <FormControlLabel
        control={<Checkbox checked={!!value} onChange={(e) => onChange(e.target.checked)} />}
        label={value ? 'true' : 'false'}
      />
    );
  }
  if (['int', 'short', 'long', 'byte'].includes(lower)) {
    return <NumericInput label="" value={value ?? 0} onChange={onChange} isFloat={false} sx={{ width: 100 }} />;
  }
  if (['float', 'double', 'decimal'].includes(lower)) {
    return <NumericInput label="" value={value ?? 0} onChange={onChange} isFloat sx={{ width: 100 }} />;
  }
  if (lower === 'string') {
    // 改行を含む文字列を入力できるようにmultiline化(仕様書項目4: 以前はEnterで改行されなかった)
    return (
      <TextField
        size="small"
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value)}
        multiline
        minRows={1}
        maxRows={8}
        sx={{ minWidth: 160 }}
      />
    );
  }
  if (lower === 'char') {
    return <TextField size="small" value={value ?? ''} onChange={(e) => onChange(e.target.value)} sx={{ minWidth: 160 }} />;
  }
  if (VECTOR_AXIS_LABELS[lower]) {
    const labels = VECTOR_AXIS_LABELS[lower];
    const arr = Array.isArray(value) ? value : Array(labels.length).fill(0);
    return (
      <Box sx={{ display: 'flex', gap: 0.5 }}>
        {labels.map((l, i) => (
          <TextField
            key={l} size="small" label={l} type="number" value={arr[i] ?? 0} sx={{ width: 64 }}
            onChange={(e) => { const next = [...arr]; next[i] = parseFloat(e.target.value) || 0; onChange(next); }}
          />
        ))}
      </Box>
    );
  }
  // Enum / ClassDataID / CustomClassDataID
  if (enumValues[type] && enumValues[type].length > 0) {
    const opts = [
      { value: `${type}ID.None`, label: 'None' },
      ...enumValues[type].map(v => {
        const val = typeof v === 'object' ? (v.property || v.enum_property || v) : v;
        return { value: `${type}ID.${val}`, label: val };
      }),
    ];
    return (
      <Autocomplete
        size="small"
        options={opts}
        getOptionLabel={(o) => o.label}
        value={opts.find(o => o.value === value) || null}
        onChange={(e, nv) => onChange(nv ? nv.value : `${type}ID.None`)}
        renderInput={(params) => <TextField {...params} size="small" />}
        isOptionEqualToValue={(o, v) => o.value === v?.value}
        sx={{ minWidth: 180 }}
      />
    );
  }
  // CustomClassData / ClassData (ネストしたオブジェクト)
  if (nestedSubSchema) {
    return <NestedClassDataField value={value} subSchema={nestedSubSchema} onChange={onChange} />;
  }
  return <TextField size="small" value={value ?? ''} onChange={(e) => onChange(e.target.value)} sx={{ minWidth: 160 }} />;
}

function DictionaryKeyEditor({ keyValue, keyType, enumValues, onChange }) {
  if ((keyType || 'int').toLowerCase() === 'int') {
    return <NumericInput label="" value={keyValue ?? 0} onChange={onChange} isFloat={false} sx={{ width: 100 }} />;
  }
  const opts = (enumValues && enumValues[keyType]) || [];
  const options = [
    { value: `${keyType}ID.None`, label: 'None' },
    ...opts.map(v => {
      const val = typeof v === 'object' ? (v.property || v.enum_property || v) : v;
      return { value: `${keyType}ID.${val}`, label: val };
    }),
  ];
  return (
    <Autocomplete
      size="small"
      options={options}
      getOptionLabel={(o) => o.label}
      value={options.find(o => o.value === keyValue) || null}
      onChange={(e, nv) => onChange(nv ? nv.value : `${keyType}ID.None`)}
      renderInput={(params) => <TextField {...params} size="small" />}
      isOptionEqualToValue={(o, v) => o.value === v?.value}
      sx={{ minWidth: 160 }}
    />
  );
}

function defaultDictScalar(t, enumValues, classDataSchemas, customClassSchemas) {
  const lower = (t || '').toLowerCase();
  if (['int', 'short', 'long', 'byte'].includes(lower)) return 0;
  if (['float', 'double', 'decimal'].includes(lower)) return 0.0;
  if (lower === 'bool') return false;
  if (lower === 'string' || lower === 'char') return '';
  if (VECTOR_AXIS_LABELS[lower]) return Array(VECTOR_AXIS_LABELS[lower].length).fill(0);
  if (lower === 'bit') return { size: 8, bits: [] };
  if (lower === 'color') return { r: 1, g: 1, b: 1, a: 1 };
  if (lower === 'bezier') return { points: [{ time: 0, value: 0, inTangent: 0, outTangent: 0 }, { time: 1, value: 1, inTangent: 0, outTangent: 0 }] };
  if (enumValues[t] && enumValues[t].length > 0) return `${t}ID.None`;
  if (customClassSchemas[t] || classDataSchemas[t]) return {};
  return '';
}

function DictionaryValueEditor({ value, options, onChange, enumValues, classDataSchemas, customClassSchemas }) {
  const keyType = options?.keyType || 'int';
  const valueType = options?.valueType || 'int';
  const valueArraySize = options?.valueArraySize ?? 0;
  const valueIsArray = valueArraySize !== 0;
  const valueOptions = options?.valueOptions || {};
  const entries = Array.isArray(value?.entries) ? value.entries : [];

  const updateEntries = (next) => onChange({ entries: next });
  const updateKey = (i, k) => updateEntries(entries.map((e, idx) => (idx === i ? { ...e, key: k } : e)));
  const updateValue = (i, v) => updateEntries(entries.map((e, idx) => (idx === i ? { ...e, value: v } : e)));
  const removeEntry = (i) => updateEntries(entries.filter((_, idx) => idx !== i));

  const addEntry = () => {
    const defaultKey = keyType.toLowerCase() === 'int' ? 0 : `${keyType}ID.None`;
    const defaultVal = valueIsArray ? [] : defaultDictScalar(valueType, enumValues, classDataSchemas, customClassSchemas);
    updateEntries([...entries, { key: defaultKey, value: defaultVal }]);
  };
  const addArrayItem = (entryIdx) => {
    const arr = Array.isArray(entries[entryIdx].value) ? entries[entryIdx].value : [];
    updateValue(entryIdx, [...arr, defaultDictScalar(valueType, enumValues, classDataSchemas, customClassSchemas)]);
  };
  const removeArrayItem = (entryIdx, itemIdx) => {
    const arr = Array.isArray(entries[entryIdx].value) ? entries[entryIdx].value : [];
    updateValue(entryIdx, arr.filter((_, i) => i !== itemIdx));
  };
  const updateArrayItem = (entryIdx, itemIdx, v) => {
    const arr = Array.isArray(entries[entryIdx].value) ? [...entries[entryIdx].value] : [];
    arr[itemIdx] = v;
    updateValue(entryIdx, arr);
  };

  return (
    <Box sx={{ border: '1px solid #e0e0e0', borderRadius: 1, p: 1 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 0.5 }}>
        <Typography variant="caption" color="text.secondary">
          {entries.length}件 / Dictionary&lt;{keyType}, {valueType}{valueIsArray ? '[]' : ''}&gt;
        </Typography>
        <Button size="small" startIcon={<AddIcon />} onClick={addEntry}>エントリを追加</Button>
      </Box>
      {entries.length === 0 && (
        <Typography variant="caption" color="text.disabled" sx={{ display: 'block', py: 1, textAlign: 'center' }}>
          エントリがありません
        </Typography>
      )}
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
        {entries.map((entry, i) => (
          <Box key={i} sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, p: 0.5, border: '1px solid #f0f0f0', borderRadius: 1 }}>
            <Box sx={{ pt: 0.5 }}>
              <DictionaryKeyEditor keyValue={entry.key} keyType={keyType} enumValues={enumValues} onChange={(v) => updateKey(i, v)} />
            </Box>
            <Typography variant="caption" sx={{ pt: 1 }}>:</Typography>
            <Box sx={{ flex: 1 }}>
              {valueIsArray ? (
                <Box>
                  {(Array.isArray(entry.value) ? entry.value : []).map((item, itemIdx) => (
                    <Box key={itemIdx} sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                      <Typography variant="caption" sx={{ minWidth: 20, color: 'text.secondary' }}>[{itemIdx}]</Typography>
                      <DictionaryScalarEditor
                        type={valueType} value={item} options={valueOptions}
                        onChange={(v) => updateArrayItem(i, itemIdx, v)}
                        enumValues={enumValues} classDataSchemas={classDataSchemas} customClassSchemas={customClassSchemas}
                      />
                      <IconButton size="small" color="error" onClick={() => removeArrayItem(i, itemIdx)}>
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Box>
                  ))}
                  <Button size="small" startIcon={<AddIcon />} onClick={() => addArrayItem(i)}>要素を追加</Button>
                </Box>
              ) : (
                <DictionaryScalarEditor
                  type={valueType} value={entry.value} options={valueOptions}
                  onChange={(v) => updateValue(i, v)}
                  enumValues={enumValues} classDataSchemas={classDataSchemas} customClassSchemas={customClassSchemas}
                />
              )}
            </Box>
            <IconButton size="small" color="error" onClick={() => removeEntry(i)}>
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Box>
        ))}
      </Box>
    </Box>
  );
}

// ============================================================
// class_data / CustomClassData のネストしたフィールドを描画するための共通ラッパー。
//
// なぜこれが必要か:
// renderField/renderSingle は BaseRoleInputForm の描画のたびに(配列要素ごとにも)
// 呼び出される「ただの関数」であり、Reactコンポーネントではない
// (Hooksのルール上、この中で直接useMemo/useCallbackは使えない)。
// そのため、以前は呼び出し箇所で毎回
//   const subInitialData = Object.entries(value || {}).map(...)
// のように新しい配列を作って <BaseRoleInputForm initialData={subInitialData} .../> に
// 渡していた。これだと「中身は同じでも参照は常に新しい」ため、フォームのどこか
// 1文字を編集して親が再レンダーされるたびに、このネストしたインスタンス側の
//   useEffect([initialData, schema, isLoading])
// が「値が変わった」と誤検知してformDataをリセット+onChangeを呼び直し、それが
// さらに親のonChangeを呼ぶ…という無駄な連鎖を引き起こしていた
// (ClassData/CustomClassDataが多い・ネストが深いフォームほど、この連鎖が
// 多重に発生して顕著に重くなっていた)。
//
// この専用コンポーネントに切り出すことで、
//  - subInitialData は「値の中身」が変わった時だけ作り直す(useMemo)
//  - 親から渡されるonChangeは毎回新しい関数でも、子への参照は安定させる(useRef)
// ということができるようになる。
function NestedClassDataField({ value, subSchema, onChange }) {
  const onChangeRef = useRef(onChange);
  useEffect(() => { onChangeRef.current = onChange; });

  const subInitialData = useMemo(
    () => Object.entries(value || {}).map(([n, v]) => ({
      name: n,
      value: v,
      arraySize: subSchema.fields.find(f => f.name === n)?.arraySize || 0,
    })),
    // 値の「参照」ではなく「中身」が変わった時だけ作り直したいのでJSON化して比較する。
    // フォームの1フィールド分の値なので、このコストは無視できるレベル。
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [JSON.stringify(value ?? null), subSchema]
  );

  const handleSubChange = useCallback((subData) => {
    const newObj = subData.reduce((acc, { name, value: v }) => { acc[name] = v; return acc; }, {});
    onChangeRef.current(newObj);
  }, []);

  return <BaseRoleInputForm schema={subSchema} initialData={subInitialData} onChange={handleSubChange} />;
}

// fieldDefaultUrl: 「デフォルト保存」(ブックマークボタン)の保存先を、Role用の
//   /api/scenario-role/<roleName>/field-default 以外に差し替えたい場合に指定する
//   (例: サブグループ設定は /api/scenario-subgroup-setting/field-default)。
//   POST {fieldName, value} を受け取れるエンドポイントであること。
const BaseRoleInputForm = ({ schema, initialData, onChange, eventId, subId, roleName, fieldDefaultUrl }) => {
  const [formData, setFormData] = useState(initialData || []);

  // 親(呼び出し元)がすでにContextでenum/classData/customClassSchemasを
  // 提供済みなら(=自分はネストした子インスタンス)、それをそのまま使い、
  // 自分では何もフェッチしない。最上位インスタンス(Contextがまだ無い)だけが
  // 下のuseEffectで実際にフェッチを行う。
  const inherited = useContext(RoleFormTypeOptionsContext);
  const isNested = inherited !== null;

  const [ownEnumValues, setOwnEnumValues] = useState({});
  const [ownClassDataSchemas, setOwnClassDataSchemas] = useState({});
  const [ownCustomClassSchemas, setOwnCustomClassSchemas] = useState({}); // CustomClassData (ネストしたオブジェクト。bit/color/bezierフィールドを含みうる)
  const [ownIsLoading, setOwnIsLoading] = useState(true);

  const enumValues = isNested ? inherited.enumValues : ownEnumValues;
  const classDataSchemas = isNested ? inherited.classDataSchemas : ownClassDataSchemas;
  const customClassSchemas = isNested ? inherited.customClassSchemas : ownCustomClassSchemas;
  const isLoading = isNested ? inherited.isLoading : ownIsLoading;

  const getDefaultValue = useCallback((type, arraySize, options) => {
    const baseDefault = () => {
      switch (type.toLowerCase()) {
        case 'int': case 'short': case 'long': case 'byte': return 0;
        case 'float': case 'double': case 'decimal': return 0.0;
        case 'char': return '';
        case 'bool': return false;
        case 'string': return '';
        case 'vector2': return [0, 0];
        case 'vector3': return [0, 0, 0];
        case 'vector4': return [0, 0, 0, 0];
        default:
          if (type === 'bit') return { size: options?.size ?? 8, bits: [] };
          if (type === 'color') return { r: 1, g: 1, b: 1, a: 1 };
          if (type === 'bezier') return { points: [{ time: 0, value: options?.min ?? 0, inTangent: 0, outTangent: 0 }, { time: 1, value: options?.max ?? 1, inTangent: 0, outTangent: 0 }] };
          if (type === 'dictionary') return { entries: [] };
          // text_list_index は int だが、0 は「0番目のテキスト」という有効な値。
          // 未選択は -1（TextListIndexFieldEditor もこの規約で描画している）。
          if (type === 'text_list_index') return -1;
          // voice_ref も text_list_index と同じ int インデックス（-1 = 未選択）。
          if (type === 'voice_ref') return -1;
          if (type in customClassSchemas) {
            const obj = {};
            (customClassSchemas[type] || []).forEach(f => { obj[f.name] = getDefaultValue(f.type, f.arraySize, f.options); });
            return obj;
          }
          if (type in enumValues && enumValues[type].length > 0) return `${type}ID.None`;
          // classDataSchemas は「TypeName.EnumID」のように選ぶID参照ではなく、
          // customClassSchemas と同じ「埋め込み構造体(ClassData)」。
          // GUI側(renderSingle の classDataSubSchemaByType 分岐)もこれをネストした
          // オブジェクトとして描画しているので、デフォルト値もオブジェクトを組み立てる
          // 必要がある。以前はここが `${type}ID.None` という文字列を返しており、
          // GUIでは Object.entries(文字列) が文字ごとに分解されてしまい描画が壊れ、
          // DSL側ではその文字列がそのままシリアライズされて
          // 「difference_id=CharacterDifferenceID.None」のような、本来ネストした
          // { scale: 0, add_position: {...} } になるべき出力が壊れる原因になっていた。
          if (type in classDataSchemas && classDataSchemas[type].length > 0) {
            const obj = {};
            (classDataSchemas[type] || []).forEach(f => { obj[f.name] = getDefaultValue(f.type, f.arraySize, f.options); });
            return obj;
          }
          return '';
      }
    };
    if (arraySize === undefined || arraySize === 0) return baseDefault();
    if (arraySize > 0) return Array.from({ length: arraySize }, () => baseDefault());
    if (arraySize === -1) return [];
    return baseDefault();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enumValues, classDataSchemas, customClassSchemas]);

  useEffect(() => {
    if (!isLoading) {
      const formattedData = schema.fields.map(field => {
        const initialItem = (initialData || []).find(d => d.name === field.name);
        // 優先順位: ①既存データの値 → ②Role側に保存済みのデフォルト値
        // （「デフォルト保存」ボタンで保存されたもの） → ③型ごとの汎用初期値
        const hasSavedDefault = field.default !== undefined && field.default !== null;
        return {
          name: field.name,
          value: initialItem
            ? initialItem.value
            : (hasSavedDefault ? field.default : getDefaultValue(field.type, field.arraySize)),
          arraySize: field.arraySize !== undefined ? field.arraySize : 0
        };
      });
      // onChangeは上の「formData変化時」useEffectが一元的に呼ぶので、ここでは
      // setFormDataだけ行う(以前はここでも直接onChangeを呼んでおり、二重通知に
      // なっていた)。
      setFormData(formattedData);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialData, schema, isLoading]);

  useEffect(() => {
    // ネストした子インスタンスはContextから受け取った結果を使い回すので、
    // ここで自分でフェッチする必要はない(setOwnIsLoadingも動かさない=
    // 上のisLoading変数はinherited.isLoadingをそのまま反映する)。
    if (isNested) return;
    setOwnIsLoading(true);
    const collectTypes = (fields) => {
      const types = new Set();
      fields.forEach(field => {
        types.add(field.type);
        if (field.subFields) collectTypes(field.subFields).forEach(t => types.add(t));
      });
      return types;
    };
    const types = [...collectTypes(schema.fields)];

    const loadData = async () => {
      try {
        const [enumListRes, classIdListRes, classDataListRes, customOptionsRes] = await Promise.all([
          fetch('/api/enum-id'),
          fetch('/api/class-data-id'),
          fetch('/api/class-data'),
          fetch('/api/custom-class-data-type-options'),
        ]);
        const enumList = enumListRes.ok ? await enumListRes.json() : [];
        const classIdList = classIdListRes.ok ? await classIdListRes.json() : [];
        const classDataList = classDataListRes.ok ? await classDataListRes.json() : [];
        const customOptions = customOptionsRes.ok ? await customOptionsRes.json() : {};
        const customClassIdList = customOptions.custom_class_id_list || [];
        // custom_class_schemas はすでにフィールド一覧(bit/color/bezierのoptions込み)が
        // まとまって返ってくるので、CustomClassData型は個別フェッチ不要でそのまま使える。
        setOwnCustomClassSchemas(customOptions.custom_class_schemas || {});

        const enumPromises = enumList
          .filter(e => types.includes(e.name))
          .map(async e => {
            const res = await fetch(`/api/enum/${encodeURIComponent(e.name)}`);
            const data = res.ok ? await res.json() : [];
            return { [e.name]: data || [] };
          });

        const classIdPromises = classIdList
          .filter(c => types.includes(c.name))
          .map(async c => {
            const res = await fetch(`/api/class-data-id/${encodeURIComponent(c.name)}`);
            const data = res.ok ? await res.json() : { rows: [] };
            return { [c.name]: (data.rows || []).map(r => r.enum_property) };
          });

        const classDataPromises = classDataList
          .filter(c => types.includes(c.name))
          .map(async c => {
            const res = await fetch(`/api/class-data/${encodeURIComponent(c.name)}`);
            const data = res.ok ? await res.json() : [];
            return { [c.name]: data || [] };
          });

        // CustomClassDataID: class_data_id と同じくID参照。値候補(enum_property一覧)を取得する。
        const customClassIdPromises = customClassIdList
          .filter(name => types.includes(name))
          .map(async name => {
            const res = await fetch(`/api/custom-class-data-id/${encodeURIComponent(name)}`);
            const data = res.ok ? await res.json() : { rows: [] };
            return { [name]: (data.rows || []).map(r => r.enum_property) };
          });

        const results = await Promise.all([...enumPromises, ...classIdPromises, ...classDataPromises, ...customClassIdPromises]);
        const valuesMap = results.reduce((acc, curr) => ({ ...acc, ...curr }), {});

        const enumMap = {};
        const classDataMap = {};
        Object.keys(valuesMap).forEach(key => {
          if (classDataList.some(item => item.name === key)) {
            classDataMap[key] = valuesMap[key];
          } else {
            // enum / class_data_id / custom_class_data_id はすべて「候補から選ぶID」なので
            // 同じ enumValues 側にまとめる(CustomClassFieldEditor同様の描画を再利用するため)
            enumMap[key] = valuesMap[key];
          }
        });

        setOwnEnumValues(prev => ({ ...prev, ...enumMap }));
        setOwnClassDataSchemas(prev => ({ ...prev, ...classDataMap }));
      } catch (error) {
        console.error('型オプション取得エラー:', error);
      } finally {
        setOwnIsLoading(false);
      }
    };

    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(schema.fields), isNested]);

  // 自分がフェッチした(または継承した)結果を、ネストした子インスタンスへ配るための
  // Context値。参照を安定させるためuseMemoでラップする。
  const typeOptionsContextValue = useMemo(
    () => ({ enumValues, classDataSchemas, customClassSchemas, isLoading }),
    [enumValues, classDataSchemas, customClassSchemas, isLoading]
  );

  // class_data/CustomClassDataのネストしたフィールドを描画する際に使うsub-schemaを
  // 事前に1回だけ組み立てておく(renderField内で毎レンダー新規オブジェクトを
  // 作ると、配列項目ごとに呼ばれるrenderSingleの中でuseMemoが使えず(hooksの
  // ルール上、可変長の配列要素ごとの呼び出しでは安全に使えない)、子コンポーネントの
  // props参照が毎回変わってしまうため)。
  const buildSubSchemaMap = (schemasByType) => {
    const map = {};
    Object.keys(schemasByType).forEach((type) => {
      const fields = schemasByType[type];
      if (fields && fields.length > 0) {
        map[type] = {
          fields: fields.map((sub) => ({
            ...sub,
            label: sub.label || sub.name,
            arraySize: sub.arraySize !== undefined ? sub.arraySize : 0,
          })),
        };
      }
    });
    return map;
  };
  // CustomClassDataとClassData(raw class_data)は別の名前空間・別の描画スタイル
  // (Chipラベルが "CustomClass" / "Class" で異なる)なので、混同しないように
  // マップは分けて持つ。
  const customClassSubSchemaByType = useMemo(
    () => buildSubSchemaMap(customClassSchemas), [customClassSchemas]
  );
  const classDataSubSchemaByType = useMemo(
    () => buildSubSchemaMap(classDataSchemas), [classDataSchemas]
  );

  const handleChange = (name, value, arraySize) => {
    setFormData(prev => prev.map(item =>
      item.name === name ? { ...item, value, arraySize: arraySize !== undefined ? arraySize : item.arraySize } : item
    ));
  };

  // formData が実際に変化したときだけ親へ通知する(handleChangeのupdater内で
  // 直接onChangeを呼ぶと、Reactのバッチ処理・StrictModeの二重呼び出しの影響で
  // 親へ余計な回数通知してしまい、そのたびに下の「ネストしたinitialData再生成」
  // 問題(後述)と合わさって入力が重くなる原因になっていた)。
  const isFirstFormDataEffect = useRef(true);
  useEffect(() => {
    if (isFirstFormDataEffect.current) {
      isFirstFormDataEffect.current = false;
      return;
    }
    onChange(formData);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formData]);

  // ── フィールドの「デフォルト保存」 ──
  // 今このフォームに入力されている値を、Role定義側(scenario_role/<Role>/<Role>.json)の
  // そのフィールドの default として保存する。以後、このRoleを他のシナリオへ新規追加した
  // 際の初期値として使われる(schema.fields[].default → BaseRoleInputForm冒頭のformattedData参照)。
  const [savingDefaultField, setSavingDefaultField] = useState(null);
  const handleSaveAsDefault = async (field) => {
    if (!roleName && !fieldDefaultUrl) return;
    const current = formData.find(d => d.name === field.name);
    setSavingDefaultField(field.name);
    try {
      const res = await fetch(fieldDefaultUrl || `/api/scenario-role/${encodeURIComponent(roleName)}/field-default`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fieldName: field.name, value: current ? current.value : null }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
    } catch (e) {
      console.error('デフォルト値保存エラー:', e);
      alert(`デフォルト値の保存に失敗しました: ${e.message}`);
    } finally {
      setSavingDefaultField(null);
    }
  };

  const renderField = (field, parentPath = '', indexPath = []) => {
    const key = parentPath ? `${parentPath}.${field.name}` : field.name;
    let currentValue = formData.find(d => d.name === (parentPath || field.name))?.value;
    indexPath.forEach(idx => { currentValue = currentValue ? currentValue[idx] : undefined; });
    if (currentValue === undefined) currentValue = getDefaultValue(field.type, field.arraySize);

    if (field.warning) {
      return <Box key={key} sx={{ color: 'error.main', p: 1, bgcolor: 'error.50', borderRadius: 1 }}>{field.warning}</Box>;
    }

    if (isLoading) {
      return (
        <Box key={key} sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
          <CircularProgress size={16} />
          <Typography variant="caption" color="text.secondary">Loading...</Typography>
        </Box>
      );
    }

    const renderSingle = (value, onValueChange) => {
      // bit / color / bezier (CustomClassDataの拡張型)
      if (field.type === 'voice_ref') {
        return (
          <VoiceRefFieldEditor
            key={key}
            value={value}
            onChange={onValueChange}
            options={field.options || {}}
            eventId={eventId}
            subId={subId}
          />
        );
      }
      if (field.type === 'text_list_index') {
        return (
          <TextListIndexFieldEditor
            key={key}
            value={value}
            onChange={onValueChange}
            options={field.options || {}}
            eventId={eventId}
            subId={subId}
          />
        );
      }
      if (field.type === 'bit') {
        return <BitValueEditor key={key} value={value} options={field.options} onChange={onValueChange} />;
      }
      if (field.type === 'color') {
        return <ColorValueEditor key={key} value={value} onChange={onValueChange} />;
      }
      if (field.type === 'bezier') {
        return <BezierValueEditor key={key} value={value} options={field.options} onChange={onValueChange} />;
      }
      if (field.type === 'dictionary') {
        return (
          <DictionaryValueEditor
            key={key}
            value={value}
            options={field.options}
            onChange={onValueChange}
            enumValues={enumValues}
            classDataSchemas={classDataSchemas}
            customClassSchemas={customClassSchemas}
          />
        );
      }

      // CustomClassData (ネストしたオブジェクト。中にbit/color/bezierを含んでもよい)
      if (customClassSubSchemaByType[field.type]) {
        const subSchema = customClassSubSchemaByType[field.type];
        return (
          <Paper key={key} variant="outlined" sx={{ p: 1.5, mb: 1, bgcolor: 'secondary.50' }}>
            <Typography variant="caption" fontWeight="bold" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              {field.label || field.name} <Chip label="CustomClass" size="small" color="secondary" sx={{ ml: 0.5, height: 16, fontSize: '0.6rem' }} />
            </Typography>
            <NestedClassDataField value={value} subSchema={subSchema} onChange={onValueChange} />
          </Paper>
        );
      }

      // Enum / class_data_id / custom_class_data_id (すべてID候補から選ぶ形なので同じ描画)
      if (enumValues[field.type] && enumValues[field.type].length > 0) {
        const options = [
          { value: `${field.type}ID.None`, label: 'None' },
          ...enumValues[field.type].map(v => {
            const val = typeof v === 'object' ? (v.property || v.enum_property || v) : v;
            return { value: `${field.type}ID.${val}`, label: val };
          })
        ];
        return (
          <Autocomplete
            key={key}
            options={options}
            getOptionLabel={(option) => option.label}
            value={options.find(opt => opt.value === value) || null}
            onChange={(e, newValue) => onValueChange(newValue ? newValue.value : `${field.type}ID.None`)}
            renderInput={params => (
              <TextField {...params} label={field.label || field.name} size="small" />
            )}
            fullWidth
            isOptionEqualToValue={(option, val) => option.value === val?.value}
          />
        );
      }

      // ClassData (nested)
      if (classDataSubSchemaByType[field.type]) {
        const subSchema = classDataSubSchemaByType[field.type];
        return (
          <Paper key={key} variant="outlined" sx={{ p: 1.5, mb: 1, bgcolor: 'grey.50' }}>
            <Typography variant="caption" fontWeight="bold" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              {field.label || field.name} <Chip label="Class" size="small" sx={{ ml: 0.5, height: 16, fontSize: '0.6rem' }} />
            </Typography>
            <NestedClassDataField value={value} subSchema={subSchema} onChange={onValueChange} />
          </Paper>
        );
      }

      const typeLower = field.type.toLowerCase();

      // String
      if (typeLower === 'string') {
        return (
          <TextField
            key={key}
            label={field.label || field.name}
            value={value ?? ''}
            onChange={e => onValueChange(e.target.value)}
            fullWidth
            size="small"
            multiline
            minRows={1}
            maxRows={8}
          />
        );
      }
      // Char (1文字想定のため単一行のまま)
      if (typeLower === 'char') {
        return (
          <TextField
            key={key}
            label={field.label || field.name}
            value={value ?? ''}
            onChange={e => onValueChange(e.target.value)}
            fullWidth
            size="small"
          />
        );
      }

      // Integer types
      if (['int', 'short', 'long', 'byte'].includes(typeLower)) {
        return (
          <NumericInput
            key={key}
            label={field.label || field.name}
            value={value ?? 0}
            onChange={onValueChange}
            isFloat={false}
            sx={{ width: '100%' }}
          />
        );
      }

      // Float types
      if (['float', 'double', 'decimal'].includes(typeLower)) {
        return (
          <NumericInput
            key={key}
            label={field.label || field.name}
            value={value ?? 0}
            onChange={onValueChange}
            isFloat={true}
            sx={{ width: '100%' }}
          />
        );
      }

      // Bool
      if (typeLower === 'bool') {
        return (
          <FormControlLabel
            key={key}
            control={
              <Checkbox
                checked={value === true || value === 'true'}
                onChange={e => onValueChange(e.target.checked)}
                size="small"
              />
            }
            label={
              <Typography variant="body2">{field.label || field.name}</Typography>
            }
          />
        );
      }

      // Vector2 / Vector3 / Vector4 → 変数名.X, 変数名.Y, ...
      if (typeLower === 'vector2' || typeLower === 'vector3' || typeLower === 'vector4') {
        const axisLabels = VECTOR_AXIS_LABELS[typeLower];
        const dim = axisLabels.length;
        const varName = field.label || field.name;
        return (
          <Box key={key} sx={{ mb: 1 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 0.5, display: 'block' }}>
              {varName}
            </Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
              {axisLabels.map((axis, i) => (
                <NumericInput
                  key={`${key}.${axis}`}
                  label={`${varName}.${axis}`}
                  value={Array.isArray(value) ? (value[i] ?? 0) : 0}
                  onChange={(newVal) => {
                    const newArr = Array.isArray(value) ? [...value] : Array(dim).fill(0);
                    newArr[i] = newVal;
                    onValueChange(newArr);
                  }}
                  isFloat={true}
                  sx={{ flex: 1 }}
                />
              ))}
            </Box>
          </Box>
        );
      }

      // Default fallback
      return (
        <TextField
          key={key}
          label={field.label || field.name}
          value={value ?? ''}
          onChange={e => onValueChange(e.target.value)}
          fullWidth
          size="small"
        />
      );
    };

    const arraySize = field.arraySize !== undefined ? field.arraySize : 0;

    // Non-array
    if (arraySize === 0) {
      return (
        <Box key={key} sx={{ mb: 1.5 }}>
          {renderSingle(currentValue, newValue => handleChange(field.name, newValue, arraySize))}
        </Box>
      );
    }

    // Array (fixed or dynamic)
    const isDynamic = arraySize === -1;
    const fixedLength = isDynamic ? undefined : arraySize;
    let arrayValue = Array.isArray(currentValue)
      ? currentValue
      : isDynamic
        ? []
        : Array.from({ length: fixedLength }, () => getDefaultValue(field.type, 0));

    const handleArrayChange = (newArray) => handleChange(field.name, newArray, arraySize);
    const addItem = () => { if (isDynamic) handleArrayChange([...arrayValue, getDefaultValue(field.type, 0)]); };
    const removeItem = (index) => { if (isDynamic) handleArrayChange(arrayValue.filter((_, i) => i !== index)); };
    const onDragEnd = (result) => {
      if (!result.destination || !isDynamic) return;
      const newArray = [...arrayValue];
      const [removed] = newArray.splice(result.source.index, 1);
      newArray.splice(result.destination.index, 0, removed);
      handleArrayChange(newArray);
    };

    return (
      <Paper key={key} variant="outlined" sx={{ mb: 2, p: 1.5 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 1, gap: 1 }}>
          <Typography variant="subtitle2">{field.label || field.name}</Typography>
          <Chip
            label={isDynamic ? `Dynamic Array (${arrayValue.length})` : `Array[${fixedLength}]`}
            size="small"
            color={isDynamic ? 'secondary' : 'default'}
            sx={{ height: 18, fontSize: '0.65rem' }}
          />
        </Box>
        {arrayValue.length === 0 && isDynamic ? (
          <Typography variant="caption" color="text.secondary">
            アイテムがありません。下の＋ボタンで追加してください。
          </Typography>
        ) : (
          <DragDropContext onDragEnd={onDragEnd}>
            <Droppable droppableId={key}>
              {(provided) => (
                <Box {...provided.droppableProps} ref={provided.innerRef}>
                  {arrayValue.map((itemValue, index) => (
                    <Draggable
                      key={`${key}-${index}`}
                      draggableId={`${key}-${index}`}
                      index={index}
                      isDragDisabled={!isDynamic}
                    >
                      {(provided) => (
                        <Box
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          sx={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 0.5,
                            mb: 0.5,
                            p: 0.5,
                            bgcolor: 'background.paper',
                            borderRadius: 1,
                            border: '1px solid',
                            borderColor: 'divider',
                          }}
                        >
                          {isDynamic && (
                            <Box {...provided.dragHandleProps} sx={{ color: 'text.disabled', cursor: 'grab', display: 'flex', alignItems: 'center' }}>
                              <DragHandleIcon fontSize="small" />
                            </Box>
                          )}
                          <Box sx={{ flex: 1 }}>
                            {renderSingle(itemValue, (newItemValue) => {
                              const newArray = [...arrayValue];
                              newArray[index] = newItemValue;
                              handleArrayChange(newArray);
                            })}
                          </Box>
                          {isDynamic && (
                            <Tooltip title="削除">
                              <IconButton size="small" color="error" onClick={() => removeItem(index)}>
                                <RemoveIcon fontSize="small" />
                              </IconButton>
                            </Tooltip>
                          )}
                        </Box>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </Box>
              )}
            </Droppable>
          </DragDropContext>
        )}
        {isDynamic && (
          <Box sx={{ mt: 1 }}>
            <Tooltip title="アイテムを追加">
              <IconButton size="small" color="primary" onClick={addItem}>
                <AddIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
        )}
      </Paper>
    );
  };

  /**
   * 依存関係（dependency）を評価する。
   * - 親が bool: enableValues に true/false が含まれるか
   * - 親が enum / class_data_id: 値が "TypeID.name" 形式でも短縮名でも一致すれば OK（OR）
   * - dependency が無い / 親が無い場合は常に表示
   */
  const isFieldEnabledByDependency = (field) => {
    const dep = field.dependency;
    if (!dep || !dep.parentFieldName) return true;
    const parentItem = formData.find(d => d.name === dep.parentFieldName);
    const parentVal = parentItem?.value;
    const enableValues = dep.enableValues || [];
    // 条件値が空のときは「親さえいれば常に有効」とみなす
    if (enableValues.length === 0) return true;

    // bool
    if (typeof parentVal === 'boolean') {
      return enableValues.some(v => {
        if (typeof v === 'boolean') return v === parentVal;
        const s = String(v).toLowerCase();
        return (s === 'true' && parentVal === true) || (s === 'false' && parentVal === false);
      });
    }

    // enum / class_data_id など文字列系
    const strVal = parentVal == null ? '' : String(parentVal);
    // "HogeID.hoge" → "hoge"
    const shortVal = strVal.includes('.') ? strVal.split('.').pop() : strVal;
    // None は常に不一致扱い
    if (!strVal || shortVal === 'None' || strVal.endsWith('.None')) return false;

    return enableValues.some(v => {
      const sv = String(v);
      const shortEnable = sv.includes('.') ? sv.split('.').pop() : sv;
      return sv === strVal || shortEnable === shortVal || sv === shortVal || shortEnable === strVal;
    });
  };

  const formBody = (
    <Box sx={{ p: 1 }}>
      {schema.fields.map((field, index) => {
        // 条件を満たさない子フィールドは非表示
        if (!isFieldEnabledByDependency(field)) return null;
        return (
          <Box key={field.name}>
            <Box sx={{ display: 'flex', alignItems: 'flex-start' }}>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                {renderField(field)}
              </Box>
              {(roleName || fieldDefaultUrl) && (
                <Tooltip title={field.default !== undefined && field.default !== null
                  ? `デフォルト保存済み（現在の値で更新できます）`
                  : `今の値をこのフィールドのデフォルト値として保存（次にこのRoleを追加した時の初期値になります）`}>
                  <span>
                    <IconButton
                      size="small"
                      color={field.default !== undefined && field.default !== null ? 'primary' : 'default'}
                      disabled={savingDefaultField === field.name}
                      onClick={() => handleSaveAsDefault(field)}
                      sx={{ mt: 0.5 }}
                    >
                      <BookmarkAddIcon fontSize="small" />
                    </IconButton>
                  </span>
                </Tooltip>
              )}
            </Box>
            {index < schema.fields.length - 1 && field.arraySize !== 0 && (
              <Divider sx={{ mb: 1 }} />
            )}
          </Box>
        );
      })}
    </Box>
  );

  // 自分がネストした子インスタンスの場合は、すでにどこかの先祖がProviderを
  // 立てているので、ここで重ねてProviderを作る必要は無い(そのまま返す)。
  // 最上位インスタンスの場合だけ、自分がフェッチした結果をProviderで配る。
  if (isNested) return formBody;
  return (
    <RoleFormTypeOptionsContext.Provider value={typeOptionsContextValue}>
      {formBody}
    </RoleFormTypeOptionsContext.Provider>
  );
};

export default BaseRoleInputForm;